`timescale 1ns / 1ps
//====================================================================
// tb_residual_add - the INT16 residual stream, on real layer-0 data.
//
//   r and o are Qwen3-0.6B layer 0's actual residual stream: r is the
//   block's input hidden state and o is o_proj's output, i.e. the two
//   sides of `xr = x + o` in attention_l0.forward_layer0 step 9.
//   Generated by tb/gen_residual_vectors.py.
//
//   R1  the well-scaled case: 1024/1024 elements bit-exact, no
//       saturation.
//   R2  THE SATURATING CASE, on purpose. |x|max is 0.068 but |o|max is
//       2.88 - o_proj's output dominates the residual by 42x - so a
//       scale sized for x alone, which is an easy and realistic
//       mistake, overflows on 251 of 1024 elements. The clamped values
//       must be bit-exact too, and ovf must latch. This is the case
//       q_scale turned out not to have; residual_add really does.
//   R3  done coincides with the final out_valid and never fires while
//       busy - the property rope and q_scale both had to be fixed for.
//   R4  results are captured BY THE INDEX THE DUT REPORTS and all 1024
//       must appear, so an off-by-one in the index pipeline cannot
//       hide behind arrival order.
//   R5  ovf is sticky within a run and cleared by the next go.
//====================================================================
module tb_residual_add;

    localparam int N  = 1024;
    localparam int RW = 16;
    localparam int MW = 16;
    localparam int SW = 6;

    logic clk = 1'b0, rst_n = 1'b0;
    always #5 clk = ~clk;

    integer errors = 0, i, bad;

    logic [15:0] r_mem  [N], r2_mem [N];
    logic [7:0]  o_mem  [N];
    logic [15:0] exp1   [N], exp2   [N];
    logic [15:0] cfg1   [2], cfg2   [2];

    initial begin
        $readmemh("tb/res_r.memh",    r_mem);
        $readmemh("tb/res_r2.memh",   r2_mem);
        $readmemh("tb/res_o.memh",    o_mem);
        $readmemh("tb/res_exp.memh",  exp1);
        $readmemh("tb/res_exp2.memh", exp2);
        $readmemh("tb/res_cfg.memh",  cfg1);
        $readmemh("tb/res_cfg2.memh", cfg2);
    end

    logic                go, busy, done, ovf;
    logic signed [MW-1:0] scale_mult;
    logic [SW-1:0]       shift_amt;
    logic                r_rd_en, o_rd_en;
    logic [9:0]          r_rd_addr, o_rd_addr;
    logic signed [RW-1:0] r_rd_data;
    logic signed [7:0]   o_rd_data;
    logic                out_valid;
    logic [9:0]          out_idx;
    logic signed [RW-1:0] out_data;

    // both buffers have the 1-cycle read latency tile_buffer has
    logic use2;
    always_ff @(posedge clk) begin
        if (r_rd_en) r_rd_data <= use2 ? $signed(r2_mem[r_rd_addr])
                                       : $signed(r_mem[r_rd_addr]);
        if (o_rd_en) o_rd_data <= $signed(o_mem[o_rd_addr]);
    end

    residual_add #(.N(N), .RW(RW), .MW(MW), .SW(SW)) dut (
        .clk(clk), .rst_n(rst_n),
        .go(go), .scale_mult(scale_mult), .shift_amt(shift_amt),
        .busy(busy), .done(done),
        .r_rd_en(r_rd_en), .r_rd_addr(r_rd_addr), .r_rd_data(r_rd_data),
        .o_rd_en(o_rd_en), .o_rd_addr(o_rd_addr), .o_rd_data(o_rd_data),
        .out_valid(out_valid), .out_idx(out_idx), .out_data(out_data),
        .ovf(ovf));

    logic signed [RW-1:0] got [N];
    logic [N-1:0]         seen;

    always_ff @(posedge clk) begin
        if (out_valid) begin
            got[out_idx]  <= out_data;
            seen[out_idx] <= 1'b1;
        end
    end

    // R3 monitors, free-running so every invocation is covered
    int ov_at_done, ov_after_done, done_while_busy, done_count, go_count;

    always @(posedge clk) if (rst_n) begin
        if (go && !busy) go_count <= go_count + 1;
        if (done) begin
            done_count <= done_count + 1;
            if (out_valid) ov_at_done      <= ov_at_done + 1;
            if (busy)      done_while_busy <= done_while_busy + 1;
        end
        if (out_valid && !busy && !done) ov_after_done <= ov_after_done + 1;
    end

    task automatic run(input logic u2, input [MW-1:0] gm, input [SW-1:0] gs);
        begin
            @(negedge clk);
            use2       = u2;
            scale_mult = gm;
            shift_amt  = gs;
            seen       = '0;
            @(negedge clk); go = 1'b1;
            @(negedge clk); go = 1'b0;
            @(posedge done);
            repeat (2) @(negedge clk);
        end
    endtask

    task automatic compare(input string tag, input integer which,
                           output integer nbad, output integer nsat);
        begin
            nbad = 0; nsat = 0;
            for (i = 0; i < N; i = i + 1) begin
                if (got[i] !== $signed((which == 1) ? exp1[i] : exp2[i])) begin
                    nbad = nbad + 1;
                    if (nbad <= 3)
                        $display("Error: %s [%0d] got %0d exp %0d", tag, i,
                                 got[i], $signed((which == 1) ? exp1[i] : exp2[i]));
                end
                if (got[i] === 16'sh7FFF || got[i] === 16'sh8000)
                    nsat = nsat + 1;
            end
        end
    endtask

    integer nsat;

    initial begin
        go = 0; use2 = 0; scale_mult = 0; shift_amt = 0; seen = '0;
        ov_at_done = 0; ov_after_done = 0; done_while_busy = 0;
        done_count = 0; go_count = 0;
        repeat (4) @(negedge clk);
        rst_n = 1'b1;
        repeat (2) @(negedge clk);

        $display("=== residual_add: real layer-0 residual stream, INT16 ===");

        // ---- R1: the well-scaled case ------------------------------
        run(1'b0, cfg1[0], cfg1[1][SW-1:0]);
        if (seen !== {N{1'b1}}) begin
            errors = errors + 1;
            $display("Error: R4 only %0d indices emitted", $countones(seen));
        end
        compare("R1", 1, bad, nsat);
        errors = errors + bad;
        if (ovf !== 1'b0) begin
            errors = errors + 1;
            $display("Error: R1 ovf set on the well-scaled case");
        end
        $display("  R1 %0d/%0d bit-exact, %0d saturated, ovf %b (mant %0d shift %0d)",
                 N - bad, N, nsat, ovf, cfg1[0], cfg1[1]);

        // ---- R2: the saturating case, on purpose -------------------
        run(1'b1, cfg2[0], cfg2[1][SW-1:0]);
        compare("R2", 2, bad, nsat);
        errors = errors + bad;
        if (ovf !== 1'b1) begin
            errors = errors + 1;
            $display("Error: R2 under-scaled case did not set ovf");
        end
        if (nsat == 0) begin
            errors = errors + 1;
            $display("Error: R2 nothing saturated - the case is vacuous");
        end
        $display("  R2 %0d/%0d bit-exact including clamps, %0d saturated, ovf %b",
                 N - bad, N, nsat, ovf);

        // ---- R5: ovf clears on the next run ------------------------
        run(1'b0, cfg1[0], cfg1[1][SW-1:0]);
        if (ovf !== 1'b0) begin
            errors = errors + 1;
            $display("Error: R5 ovf stayed set after a clean run");
        end
        compare("R5", 1, bad, nsat);
        errors = errors + bad;
        $display("  R5 ovf cleared by the next go, %0d/%0d still exact", N - bad, N);

        // ---- R3: done timing ---------------------------------------
        if (done_count !== go_count) begin
            errors = errors + 1;
            $display("Error: R3 %0d done for %0d go", done_count, go_count);
        end
        if (ov_after_done !== 0) begin
            errors = errors + 1;
            $display("Error: R3 %0d beat(s) arrived after done", ov_after_done);
        end
        if (ov_at_done !== done_count) begin
            errors = errors + 1;
            $display("Error: R3 done coincided with the last beat %0d/%0d times",
                     ov_at_done, done_count);
        end
        if (done_while_busy !== 0) begin
            errors = errors + 1;
            $display("Error: R3 done asserted %0d time(s) while busy",
                     done_while_busy);
        end
        $display("  R3 %0d done pulses, each on the final beat, none while busy",
                 done_count);

        if (errors == 0) $display("ALL TESTS PASSED");
        else             $display("FAILED with %0d errors", errors);
        $finish;
    end

    initial begin
        #5000000;
        $display("Error: timeout");
        $display("FAILED");
        $finish;
    end

endmodule
